use super::*;
#[tokio::test]
async fn generic_detail_indexes_all_verified_seasons_and_pages_exact_children_without_extra_provider_reads(){
 let (mut app,original,_)=server().await;original.abort();let calls=Arc::new(AtomicUsize::new(0));let count=calls.clone();
 let router=Router::new().route("/anime/39508",get(||async{axum::Json(json!({"title":"Fixture anime","type":"anime","anime_type":"tv","ids":{"simkl":39508}}))})).route("/anime/episodes/39508",get(move ||{let count=count.clone();async move{count.fetch_add(1,Ordering::SeqCst);axum::Json(Value::Array((1..=60).map(|n|json!({"title":format!("Episode {n}"),"type":"episode","aired":true,"ids":{"simkl":1000+n},"tvdb":{"season":if n<=30{1}else{2},"episode":if n<=30{n}else{n-30}}})).collect()))}}));
 let listener=tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();let address=listener.local_addr().unwrap();let task=tokio::spawn(async move{axum::serve(listener,router).await.unwrap()});app.simkl=Arc::new(Service::fixture(&format!("http://{address}")));
 let path="/api/meta/series/simkl%3Aanime%3A39508";let(status,first)=request(&app,"member-token-1","GET",path,json!({})).await;assert_eq!(status,StatusCode::OK,"{first}");assert_eq!(first["episodes"].as_array().unwrap().len(),24);assert_eq!(first["next_cursor"],"24");assert_eq!(first["seasons"],json!([{ "season":1,"episode_count":30,"offset":0},{"season":2,"episode_count":30,"offset":30}]));
 let(status,second)=request(&app,"member-token-1","GET",&format!("{path}?offset=30"),json!({})).await;assert_eq!(status,StatusCode::OK);assert_eq!(second["episodes"][0]["identity"]["episode"],json!({"season":2,"episode":1,"order":"aired"}));assert_eq!(second["episodes"][0]["parent_identity"],first["item"]["identity"]);assert_eq!(second["next_cursor"],"54");
 let(status,last)=request(&app,"member-token-1","GET",&format!("{path}?offset=54"),json!({})).await;assert_eq!(status,StatusCode::OK);assert_eq!(last["episodes"].as_array().unwrap().len(),6);assert!(last["next_cursor"].is_null());assert_eq!(calls.load(Ordering::SeqCst),1);task.abort();
}
